Future<bool> setAndSavePath(String path) async {
  final dir = Directory(path);
  if (!await dir.exists()) {
    try {
      await dir.create(recursive: true);
    } on FileSystemException catch (e) {
      debugPrint('[StorageService] cannot create $path: $e');
      return false;
    }
  }
  _downloadPath = path;
  await _savePath(path);
  return true;
}
